# Stage S15a (11/05), generated by make_s15.py: refinement of the baseline sweeps behind a number of the text.
# Rule as refine_points.py: quarter points of [peak rate, next tested rate], ascending until one fails the criterion;
# if the peak rate is saturated (goodput < 90% of the offered rate), also those of [previous tested rate, peak rate].
# 11/05: only the sweeps whose peak a figure or the text shows; above the peak a run that sustains but is
# saturated (goodput < 95% of the offered rate) ends the refinement, below a saturated peak the first unsaturated
# sustained rate does (descending), so no run is spent where the peak cannot move.
XNAME=s15a
saturated() { local g; g=$(echo "$1" | grep -oE "whole_goodput=[0-9]+" | head -1 | cut -d= -f2); [ -n "$g" ] && [ $((g * 100)) -lt $(($2 * 95)) ]; }
xbody() {
  local R=$D/scripts/srv_run_evm6w.sh
  local RXO2="rxo2 epr 1 1 oldqueue REEXEC=1 REEXEC_BIN=$D/bin/d16reexec_v2 FX_EPR_PROG=1 REEXEC_ALL=1"
  local mode sc wl up down x s img vc evm q ds gen r res extra
  while read -r mode sc wl up down; do
    case $sc in htf2) x="$HTF2";; rxo2) x="$RXO2";; fs) x="$FS";; fpp) x="$FPP";; fifo) x="$FIFO";; depg) x="$DEPG";; esac
    set -- $x; s=$1 img=$2 vc=$3 evm=$4 q=$5; shift 5
    read -r ds gen <<< "$(dsof $wl)"
    extra=""; [ $mode = rk ] && extra="FX_RETRY=50"
    case $wl in dex*) extra="$extra OUTSTANDING=30000";; *0M) extra="$extra FX_OL_SECONDS=30 OUTSTANDING=200000";; esac
    # below a saturated peak (listed descending): the first rate that sustains unsaturated is the highest such rate
    for r in ${down//,/ }; do
      [ "$r" = - ] && continue
      res=$(run ${mode}_${wl}_${s}_r$r $img $vc $evm $q $ds $gen FX_RATE=$r "$@" $extra < /dev/null)
      if sustained "$res" $mode && ! saturated "$res" $r; then echo "REFINE_OK ${mode}_${wl}_${s} at r=$r" | tee -a $out; break; fi
      echo "REFINE_NEXT ${mode}_${wl}_${s} at r=$r" | tee -a $out
    done
    # above the peak (ascending): stop at the first rate that fails, or that sustains but is saturated (past the knee)
    for r in ${up//,/ }; do
      [ "$r" = - ] && continue
      res=$(run ${mode}_${wl}_${s}_r$r $img $vc $evm $q $ds $gen FX_RATE=$r "$@" $extra < /dev/null)
      if ! sustained "$res" $mode; then echo "REFINE_STOP ${mode}_${wl}_${s} at r=$r" | tee -a $out; break; fi
      if saturated "$res" $r; then echo "REFINE_STOP ${mode}_${wl}_${s} at r=$r (saturated)" | tee -a $out; break; fi
      echo "REFINE_OK ${mode}_${wl}_${s} at r=$r" | tee -a $out
    done
    save
  done <<'TAB'
rk fifo dex16 137,175,212 -
rk fifo sb0.8 562,625,687 -
rk fifo sb1.0 137,175,212 -
rk fifo usdc 137,175,212 -
rk fifo usdt 146,156,165 127,118,109
rk fifo z0 13250,13500,13750 -
rk fifo z0.8 137,175,212 -
rk fpp dex1 6,7,8 -
rk fpp dex16 31,37,43 -
rk fpp sb0 4125,4250,4375 -
rk fpp sb0.6 3562,3625,3687 -
rk fpp sb0.8 137,175,212 -
rk fpp sb1.0 62,75,87 -
rk fpp sb1.2 13,17,21 -
rk fpp usdc 31,37,43 -
rk fpp usdt 13,17,21 -
rk fpp z0 3312,3375,3437 -
rk fpp z0.6 184,193,202 -
rk fs dex1 13,17,21 8,7,6
rk fs dex16 137,175,212 -
rk fs sb0 2562,2625,2687 -
rk fs sb0.6 2562,2625,2687 -
rk fs sb0.8 1250,1500,1750 -
rk fs sb1.0 625,750,875 -
rk fs sb1.2 31,37,43 -
rk fs usdc 312,375,437 -
rk fs usdt 390,406,421 -
rk fs z0 2062,2125,2187 -
rk fs z0.6 1062,1125,1187 -
pk depg dex16 62,75,87 -
pk depg sb0 - 22750,22500,22250
pk depg sb0.8 312,375,437 212,175,137
pk depg sb1.0 62,75,87 -
pk depg usdc 62,75,87 43,37,31
pk depg usdt 112,125,137 87,75,62
pk depg z0 - 22750,22500,22250
pk depg z0.8 62,75,87 -
TAB
  echo "S15A refinements done" | tee -a $out
}
